func (writer *DepthSnapshot) String() string {
	var builder strings.Builder
	builder.WriteString("{\"Name\": \"DepthSnapshot\", ")
	builder.WriteString(fmt.Sprintf("\"sbeTemplateId\": %d", writer.SbeTemplateId()))
	builder.WriteString(", ")

	builder.WriteString(`"symbolId": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.SymbolId()))

	builder.WriteString(", ")
	builder.WriteString(`"stream": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.Stream()))

	builder.WriteString(", ")
	builder.WriteString(`"bookEpoch": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.BookEpoch()))

	builder.WriteString(", ")
	builder.WriteString(`"updateId": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.UpdateId()))

	builder.WriteString(", ")
	builder.WriteString(`"transactTsNs": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.TransactTsNs()))

	builder.WriteString(", ")
	builder.WriteString(`"sendTsNs": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.SendTsNs()))

	builder.WriteString(", ")
	builder.WriteString(`"levelsPerSide": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.LevelsPerSide()))

	builder.WriteString(", ")
	{
		atLeastOne := false
		builder.WriteString(`"bids": [`)
		writer.Bids().ForEach(
			func(value *DepthSnapshotBids) {
				if atLeastOne {
					builder.WriteString(", ")
				}
				atLeastOne = true
				builder.WriteString(value.String())
			})
		builder.WriteString("]")
	}

	builder.WriteString(", ")
	{
		atLeastOne := false
		builder.WriteString(`"asks": [`)
		writer.Asks().ForEach(
			func(value *DepthSnapshotAsks) {
				if atLeastOne {
					builder.WriteString(", ")
				}
				atLeastOne = true
				builder.WriteString(value.String())
			})
		builder.WriteString("]")
	}

	builder.WriteString("}")

	return builder.String()
}

func (m *DepthSnapshot) Skip() {
	for BidsGroup := m.Bids(); BidsGroup.HasNext(); {
		BidsGroup.Next().Skip()
	}
	for AsksGroup := m.Asks(); AsksGroup.HasNext(); {
		AsksGroup.Next().Skip()
	}
}

func (m *DepthSnapshot) IsConstLength() bool {
	return false
}

func (m *DepthSnapshot) ComputeLength(
	BidsLength int,
	AsksLength int) (int, error) {
	length := uint64(m.SbeBlockLength())

	length += m.Bids().SbeHeaderSize()
	if BidsLength > 65534 {
		panic(fmt.Sprintf("BidsLength outside of allowed range [E110]"))
	}
	length += uint64(BidsLength) * m.Bids().SbeBlockLength()

	length += m.Asks().SbeHeaderSize()
	if AsksLength > 65534 {
		panic(fmt.Sprintf("AsksLength outside of allowed range [E110]"))
	}
	length += uint64(AsksLength) * m.Asks().SbeBlockLength()

	return int(length), nil
}
